css:
.maritima-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #14202e;
    background: linear-gradient(170deg, #0a1626 0%, #0f2336 42%, #123047 100%);
    border-radius: 18px;
}

.maritima-container * {
    box-sizing: border-box;
}

.maritima-header {
    text-align: center;
    padding: 30px 22px 26px;
    background:
        radial-gradient(circle at 50% -40%, rgba(212,175,90,0.18), transparent 60%),
        linear-gradient(135deg, #0c2032 0%, #103755 55%, #0c5a5a 100%);
    color: #eef6fb;
    border-radius: 16px;
    border: 1px solid rgba(212,175,90,0.28);
    margin-bottom: 18px;
    box-shadow: 0 16px 38px rgba(4, 12, 22, 0.55);
}

.maritima-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.maritima-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #e7c878;
    background: rgba(212, 175, 90, 0.12);
    border: 1px solid rgba(212, 175, 90, 0.40);
    padding: 5px 15px;
    border-radius: 999px;
}

.maritima-subtitle {
    margin: 0 auto;
    max-width: 850px;
    font-size: 1rem;
    line-height: 1.58;
    color: #c4dcec;
}

.maritima-econ {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.maritima-econ-cell {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(231, 200, 120, 0.18);
    border-radius: 12px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.maritima-econ-k {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 700;
    color: #8fb2c8;
}

.maritima-econ-v {
    font-size: 0.94rem;
    font-weight: 800;
    color: #f3e7c6;
}

.maritima-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b7d0e0;
    margin-bottom: 16px;
    padding: 2px 4px;
}

.maritima-period-counter #currentDay,
.maritima-period-counter #maxPeriods {
    font-weight: 800;
    color: #e7c878;
}

.maritima-round-name {
    background: rgba(12, 90, 90, 0.45);
    color: #7fe6d8;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(127, 230, 216, 0.3);
}

.maritima-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #e7c878;
    background: rgba(212, 175, 90, 0.12);
    border: 1px solid rgba(212, 175, 90, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.maritima-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.maritima-status-card {
    background: #fbfaf5;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 8px 20px rgba(4, 12, 22, 0.35);
    border-top: 4px solid #103755;
}

.maritima-card-trade { border-top-color: #0c8f7a; }
.maritima-card-jobs { border-top-color: #2f6fb0; }
.maritima-card-comp { border-top-color: #b8902f; }
.maritima-card-fiscal { border-top-color: #8a5cc0; }

.maritima-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7b89;
}

.maritima-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.08;
    margin: 4px 0 2px;
    color: #14202e;
    font-variant-numeric: tabular-nums;
}

.maritima-card-trade .maritima-value { color: #0c8f7a; }
.maritima-card-jobs .maritima-value { color: #2f6fb0; }
.maritima-card-comp .maritima-value { color: #b8902f; }
.maritima-card-fiscal .maritima-value { color: #8a5cc0; }

.maritima-sublabel {
    font-size: 0.74rem;
    color: #7b8b98;
    line-height: 1.38;
}

/* Competitiveness card turns red when it nears or breaches the 60 floor. */
.maritima-card-comp.maritima-comp-warn { border-top-color: #d68a1e; }
.maritima-card-comp.maritima-comp-warn .maritima-value { color: #c4791a; }
.maritima-card-comp.maritima-comp-danger { border-top-color: #cf3b3b; }
.maritima-card-comp.maritima-comp-danger .maritima-value { color: #cf3b3b; }

/* Jobs card story: green when net positive, red when net displacement. */
.maritima-card-jobs.maritima-jobs-good .maritima-value { color: #0c8f7a; }
.maritima-card-jobs.maritima-jobs-bad .maritima-value { color: #cf3b3b; }

/* Fiscal hole: red when an unfunded gap remains. */
.maritima-card-fiscal.maritima-fiscal-bad .maritima-value { color: #cf3b3b; }
.maritima-card-fiscal.maritima-fiscal-good .maritima-value { color: #0c8f7a; }

.maritima-bars {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.maritima-bar {
    display: flex;
    flex-direction: column;
    gap: 4px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.10);
    border-radius: 12px;
    padding: 12px 16px;
    font-weight: 700;
}

.maritima-bar-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #8fb2c8;
}

.maritima-bar span:last-child {
    font-size: 1.12rem;
    font-weight: 800;
    color: #f3e7c6;
}

.maritima-floor-bar span:last-child { color: #7fe6d8; }
.maritima-floor-bar.maritima-floor-warn span:last-child { color: #f0b450; }
.maritima-floor-bar.maritima-floor-danger { border-color: rgba(207,59,59,0.6); }
.maritima-floor-bar.maritima-floor-danger span:last-child { color: #ff7a7a; }

.maritima-drain-bar.maritima-drain-bad span:last-child { color: #ff7a7a; }

.maritima-briefing {
    display: flex;
    gap: 14px;
    background: #fbfaf5;
    border-left: 5px solid #0c8f7a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(4, 12, 22, 0.30);
}

.maritima-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.maritima-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #103755;
    margin-bottom: 6px;
}

.maritima-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #36475a;
}

.maritima-briefing-text strong { color: #0c5a5a; }
.maritima-briefing-text em { color: #b8902f; font-style: italic; }

.maritima-controls {
    background: #fbfaf5;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(4, 12, 22, 0.30);
}

.maritima-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #103755;
    border-bottom: 2px solid #e7e1d2;
    padding-bottom: 8px;
}

.maritima-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283a4c;
    margin: 14px 0 6px;
}

.maritima-container select,
.maritima-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6ccc0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #14202e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.maritima-container select:focus,
.maritima-container input[type="number"]:focus {
    outline: none;
    border-color: #0c8f7a;
    box-shadow: 0 0 0 3px rgba(12, 143, 122, 0.16);
}

.maritima-container select option {
    background-color: #ffffff;
    color: #14202e;
}

.maritima-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0c8f7a;
}

.maritima-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #46596b;
    margin-top: 4px;
}

.maritima-range-readout span:nth-child(2) {
    color: #0c8f7a;
    font-weight: 800;
}

.maritima-alloc-readout {
    margin-top: 14px;
    padding: 10px 14px;
    background: #f1efe4;
    border: 1px solid #e0dac9;
    border-radius: 10px;
    font-size: 0.92rem;
    font-weight: 700;
    color: #36475a;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.maritima-alloc-readout #allocReadout {
    color: #0c5a5a;
    font-weight: 800;
}

.maritima-alloc-remain {
    margin-left: auto;
    font-size: 0.84rem;
    font-weight: 700;
}

.maritima-alloc-remain.maritima-alloc-over { color: #cf3b3b; }
.maritima-alloc-remain.maritima-alloc-ok { color: #0c8f7a; }

.maritima-hint {
    font-size: 0.8rem;
    color: #7b8b98;
    margin-top: 6px;
    line-height: 1.42;
    font-style: italic;
}

.maritima-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.maritima-container .btn-primary {
    background: linear-gradient(135deg, #0c5a5a 0%, #0c8f7a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(12, 90, 90, 0.40);
}

.maritima-container .btn-primary:hover {
    filter: brightness(1.08);
}

.maritima-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6ccc0;
    color: #5a6b6a;
    background: transparent;
}

.maritima-coach {
    background: linear-gradient(160deg, #0c2032 0%, #103755 100%);
    color: #d7e8f2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(231, 200, 120, 0.22);
    box-shadow: 0 8px 22px rgba(4, 12, 22, 0.45);
}

.maritima-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c878;
    margin-bottom: 8px;
}

.maritima-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.maritima-coach-body strong { color: #7fe6d8; }
.maritima-coach-body em { color: #e7c878; font-style: italic; }

.maritima-history,
.maritima-chart {
    background: #fbfaf5;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(4, 12, 22, 0.30);
}

.maritima-history h3,
.maritima-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #103755;
}

.maritima-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #36475a;
}

.maritima-container table#usfHistoryTable th {
    background: #eef0e8;
    color: #0c5a5a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dad4c4;
}

.maritima-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ecebe2;
    color: #36475a;
}

.maritima-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f5f4ec;
}

.maritima-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .maritima-container {
        padding: 14px;
    }
    .maritima-header h1 {
        font-size: 1.7rem;
    }
    .maritima-econ {
        grid-template-columns: repeat(2, 1fr);
    }
    .maritima-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .maritima-value {
        font-size: 2rem;
    }
    .maritima-bars {
        grid-template-columns: 1fr;
    }
    .maritima-clock {
        margin-left: 0;
    }
    .maritima-period-counter {
        font-size: 0.88rem;
    }
    .maritima-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0 completion debrief (append-only, namespaced .ir-cm-*) ───────────── */
.ir-cm { color: #14202e; font-family: inherit; padding: 4px 2px 2px; }
.ir-cm-head { display: flex; align-items: center; gap: 18px; margin-bottom: 16px;
    border-bottom: 1px solid rgba(20,32,46,0.12); padding-bottom: 14px; }
.ir-cm-score { display: flex; align-items: baseline; line-height: 1; padding: 10px 16px; border-radius: 14px;
    background: rgba(184,144,47,0.12); border: 1px solid rgba(184,144,47,0.40); }
.ir-cm-score-num { font-size: 2.6rem; font-weight: 800; color: #b8902f; }
.ir-cm-score-den { font-size: 1rem; color: #76889a; margin-left: 2px; }
.ir-cm-title { font-size: 0.82rem; letter-spacing: .5px; text-transform: uppercase; color: #76889a; margin-bottom: 4px; }
.ir-cm-verdict { font-size: 1.35rem; font-weight: 700; color: #14202e; }
.ir-cm-grade { display: inline-block; margin-left: 8px; padding: 1px 10px; border-radius: 999px;
    font-size: 0.9rem; font-weight: 700; background: rgba(20,32,46,0.08); color: #2f4256; vertical-align: middle; }
.ir-cm-tier-top .ir-cm-score { background: rgba(12,143,122,0.12); border-color: rgba(12,143,122,0.45); }
.ir-cm-tier-top .ir-cm-score-num { color: #0c8f7a; }
.ir-cm-tier-low .ir-cm-score { background: rgba(193,58,58,0.10); border-color: rgba(193,58,58,0.40); }
.ir-cm-tier-low .ir-cm-score-num { color: #c13a3a; }
.ir-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 14px; }
.ir-cm-kpi { flex: 1 1 120px; min-width: 110px; padding: 10px 12px; border-radius: 10px;
    background: rgba(20,32,46,0.04); border: 1px solid rgba(20,32,46,0.10); }
.ir-cm-kpi-val { font-size: 1.15rem; font-weight: 700; color: #14202e; }
.ir-cm-kpi-lbl { font-size: 0.72rem; letter-spacing: .3px; text-transform: uppercase; color: #76889a; margin-top: 3px; }
.ir-cm-targets { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin-bottom: 14px;
    font-size: 0.92rem; color: #2f4256; }
.ir-cm-tgt-label { font-weight: 700; color: #76889a; }
.ir-cm-chip { display: inline-block; margin-left: 6px; padding: 1px 8px; border-radius: 999px; font-size: 0.8rem; font-weight: 700; }
.ir-cm-chip-ok { background: rgba(12,143,122,0.16); color: #0c8f7a; }
.ir-cm-chip-no { background: rgba(193,58,58,0.14); color: #c13a3a; }
.ir-cm-insights-label { font-size: 0.82rem; letter-spacing: .4px; text-transform: uppercase; color: #76889a; margin-bottom: 6px; }
.ir-cm-insights { margin: 0; padding-left: 20px; }
.ir-cm-insights li { margin-bottom: 6px; line-height: 1.45; color: #24384c; }

