(function() {
    'use strict';

    class IntegrateRegionAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Integrate the Region`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- NUMBERS REFERENCE CARD (Republic of Maritima, MRD) ----
            this.START_COMP = 62.0;        // competitiveness index now
            this.COMP_FLOOR = 60.0;        // PM mandate: must not fall below 60
            this.FUND = 9.6;               // development fund (MRD bn) — hard ceiling
            this.TARIFF_HOLE = 2.1;        // tariff revenue at risk (MRD bn/yr)
            this.COFIN = 3.4;              // co-financing forfeited if below bloc minimum
            this.MAX_GAINS = 6.0;          // trade gains at full+immediate (the seductive baseline)
            this.JOBS_EXPOSED = 88;        // worst-case displacement (thousands) at full speed
            this.DRAIN_MAX = 13.4;         // skilled-labour outflow (thousands) under full recognition
            this.ALLOC_THRESHOLD = 2.6;    // a fund line below this clears no real threshold

            // Concept truths (the modelled path).
            this.TRUE_OFFENSIVE = `electronics`;
            this.TRUE_DEFENSIVE = `garments`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trade: 0,           // trade gains (MRD bn)
                    jobs: 0,            // net employment effect (thousands of jobs)
                    comp: this.START_COMP,  // competitiveness index
                    fiscal: 0,          // unfunded fiscal gap the Finance Minister sees (MRD bn)
                    fundUsed: 0,        // development fund committed (MRD bn)
                    drain: 0,           // skilled-labour outflow this run (thousands)
                    // Sticky run-defining penalty flags — set when an error is committed,
                    // gate the top verdict and cap KPIs (a later good round cannot wash them out).
                    floorBreached: false,      // competitiveness fell below 60 → schedule politically dead
                    speedOverSequence: false,  // opened ALL sectors at once → the headline anti-pattern; sticky, gates top verdict
                    coFinForfeited: false,     // schedule below bloc minimum → lost MRD 3.4bn + seat
                    brainDrainRun: false,      // full recognition without retention → talent hemorrhage
                    evenSplitRun: false,       // fund divided into equal slices → nothing clears threshold
                    fiscalHoleRun: false,      // tariff hole left unfunded → structural budget gap
                    seatLost: false,           // lost the rule-setting seat at the bloc table
                    tradeHistory: [0],
                    jobsHistory: [0],
                    compHistory: [this.START_COMP],
                    fiscalHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind click-through
                // (open everything fast, full recognition, even split, ignore the fisc)
                // must NOT auto-win. It triggers the headline floor breach.
                state.decisions = {
                    offensive: `garments`,
                    defensive: `electronics`,
                    baseline: `speed`,
                    rigour: 35,
                    phasing: `immediate`,
                    labour: `full`,
                    blocMin: `meet`,
                    safeguard: 20,
                    retrain: 1.6,
                    fiscalRep: 1.6,
                    talent: 1.6,
                    sme: 1.6,
                    facil: 1.6,
                    shock: `nothing`,
                    rebalance: `none`,
                    pitch: `gains`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const off = document.getElementById(`offensiveInput`);
                const def = document.getElementById(`defensiveInput`);
                const ba = document.getElementById(`baselineInput`);
                const ri = document.getElementById(`rigourInput`);
                if (off) decisions.offensive = off.value;
                if (def) decisions.defensive = def.value;
                if (ba) decisions.baseline = ba.value;
                if (ri) decisions.rigour = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const ph = document.getElementById(`phasingInput`);
                const la = document.getElementById(`labourInput`);
                const bm = document.getElementById(`blocMinInput`);
                const sg = document.getElementById(`safeguardInput`);
                if (ph) decisions.phasing = ph.value;
                if (la) decisions.labour = la.value;
                if (bm) decisions.blocMin = bm.value;
                if (sg) decisions.safeguard = parseInt(sg.value, 10);
                if (!Number.isFinite(decisions.safeguard) || decisions.safeguard < 0 || decisions.safeguard > 100) {
                    warn(`warn_safeguard_range`); return false;
                }
            } else if (round === 3) {
                const fields = [`retrainInput`, `fiscalRepInput`, `talentInput`, `smeInput`, `facilInput`];
                const keys = [`retrain`, `fiscalRep`, `talent`, `sme`, `facil`];
                let total = 0;
                for (let i = 0; i < fields.length; i++) {
                    const el = document.getElementById(fields[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                    const v = decisions[keys[i]];
                    if (!Number.isFinite(v) || v < 0) { warn(`warn_alloc_value`); return false; }
                    total += v;
                }
                // Hard ceiling: cannot allocate more than the MRD 9.6bn fund.
                if (total > this.FUND + 0.0001) { warn(`warn_alloc_over`); return false; }
            } else if (round === 4) {
                const sh = document.getElementById(`shockInput`);
                const re = document.getElementById(`rebalanceInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sh) decisions.shock = sh.value;
                if (re) decisions.rebalance = re.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let tradeDelta = 0, jobsDelta = 0, compDelta = 0, fiscalDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose: read comparative advantage correctly, frame the baseline ----
                // Correct offensive sector = electronics (highest RCA).
                if (d.offensive === this.TRUE_OFFENSIVE) { tradeDelta += 0.6; compDelta += 0.5; }
                else if (d.offensive === `garments`) { tradeDelta -= 0.2; jobsDelta -= 6; coachKey = `coach_r1_offgarments`; }
                else { tradeDelta -= 0.1; fiscalDelta += 0.3; }

                // Correct defensive (sharpest gains-vs-jobs tension) = garments.
                if (d.defensive === this.TRUE_DEFENSIVE) { jobsDelta += 6; compDelta += 0.4; }
                else if (d.defensive === `electronics`) { tradeDelta -= 0.4; coachKey = `coach_r1_defelec`; }
                else { jobsDelta -= 2; }

                // Framing the bloc's "full and immediate" schedule.
                switch (d.baseline) {
                    case `benchmark`:
                        // Treats it as a welfare baseline to beat — the modelled read.
                        compDelta += 0.6; tradeDelta += 0.2; coachKey = `coach_r1_benchmark`; break;
                    case `speed`:
                        // The headline error seed: speed as the prize. Sets up the floor risk.
                        tradeDelta += 0.4; compDelta -= 0.8; jobsDelta -= 4; coachKey = `coach_r1_speed`; break;
                    case `reject`:
                        // Reflexive protectionism framing.
                        tradeDelta -= 0.6; coachKey = `coach_r1_reject`; break;
                }

                // Diagnostic rigour buffers competitiveness — bad schedules come from thin analysis.
                if (d.rigour >= 60) { compDelta += 0.6; }
                else if (d.rigour <= 25) { compDelta -= 0.4; coachKey = `coach_r1_norigour`; }

                summaryKey = (d.offensive === this.TRUE_OFFENSIVE && d.defensive === this.TRUE_DEFENSIVE && d.baseline === `benchmark`)
                    ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Plan: phasing, labour mobility, bloc-minimum, safeguard ----
                const safe = d.safeguard / 100;

                // Tariff phasing: the core sequencing lever.
                switch (d.phasing) {
                    case `immediate`:
                        // HEADLINE ANTI-PATTERN (Common Error #1 "Speed over sequence"):
                        // open everything at once for max gains. Big trade number, but the
                        // competitiveness floor takes a heavy hit and garment displacement runs
                        // to the top of the range. This is a STICKY, run-defining error: a buffer
                        // (safeguard headroom, retention) can soften the index arithmetic, but it
                        // cannot un-make the choice to open all sectors at once — the flag gates the
                        // top verdict and caps the composite so a good R3/R4 cannot launder it.
                        tradeDelta += 3.4;
                        jobsDelta -= 60;
                        compDelta -= 5.0 + (1 - safe) * 1.2;  // less safeguard = deeper cut
                        fiscalDelta += this.TARIFF_HOLE;       // all tariffs gone at once
                        ds.speedOverSequence = true;
                        coachKey = `coach_r2_immediate`;
                        break;
                    case `phased`:
                        // The modelled sequence: offensive fast, defensive slow.
                        tradeDelta += 2.4;
                        jobsDelta -= 14;
                        compDelta += 1.2;
                        fiscalDelta += this.TARIFF_HOLE * 0.55;
                        coachKey = `coach_r2_phased`;
                        break;
                    case `slow`:
                        // Reflexive protectionism: tiny gains, and below the bloc minimum.
                        tradeDelta += 0.6;
                        jobsDelta += 4;
                        compDelta -= 0.4;
                        fiscalDelta += this.TARIFF_HOLE * 0.2;
                        ds.coFinForfeited = true;     // slower than the bloc minimum
                        ds.seatLost = true;
                        coachKey = `coach_r2_slow`;
                        break;
                }

                // Labour-mobility regime (two-sided economics).
                switch (d.labour) {
                    case `full`:
                        // STICKY: full recognition with no retention = brain drain.
                        tradeDelta += 1.2;            // services-export upside
                        compDelta -= 2.0;             // talent leaves the upgrade sectors
                        ds.drain = this.DRAIN_MAX;
                        ds.brainDrainRun = true;
                        coachKey = `coach_r2_fulllabour`;
                        break;
                    case `retention`:
                        // Recognition WITH retention — the counter-lever path.
                        tradeDelta += 0.9;
                        compDelta += 1.3;
                        ds.drain = 4.0;
                        ds.brainDrainRun = false;
                        break;
                    case `staged`:
                        tradeDelta += 0.5;
                        compDelta += 0.6;
                        ds.drain = 6.5;
                        ds.brainDrainRun = false;
                        break;
                }

                // Bloc-minimum confirmation (strategic cost of being slow / overshooting).
                switch (d.blocMin) {
                    case `meet`:
                        compDelta += 0.5; coachKey = (d.phasing === `phased`) ? `coach_r2_meet` : coachKey; break;
                    case `below`:
                        ds.coFinForfeited = true; ds.seatLost = true;
                        fiscalDelta += 0.4; compDelta -= 0.8; coachKey = `coach_r2_below`; break;
                    case `overshoot`:
                        // Opening faster than even the bloc asks worsens the floor and jobs.
                        compDelta -= 2.2; jobsDelta -= 18; tradeDelta += 0.6; coachKey = `coach_r2_overshoot`; break;
                }

                // Safeguard headroom cushions the competitiveness path (matters at the shock).
                if (d.safeguard >= 40) { compDelta += 0.8; }
                else if (d.safeguard <= 10) { compDelta -= 0.3; }

                summaryKey = (d.phasing === `phased` && d.labour === `retention` && d.blocMin === `meet`)
                    ? `sum_r2_good`
                    : (d.phasing === `immediate` ? `sum_r2_speed`
                    : (d.phasing === `slow` || d.blocMin === `below` ? `sum_r2_protect` : `sum_r2_weak`));
            } else if (round === 3) {
                // ---- Decide: allocate the MRD 9.6bn development fund ----
                const r = { retrain: d.retrain, fiscalRep: d.fiscalRep, talent: d.talent, sme: d.sme, facil: d.facil };
                const total = r.retrain + r.fiscalRep + r.talent + r.sme + r.facil;
                ds.fundUsed = Math.round(total * 10) / 10;

                // Even-slice detection: all five lines within a narrow band → nothing clears threshold.
                const vals = [r.retrain, r.fiscalRep, r.talent, r.sme, r.facil];
                const maxV = Math.max.apply(null, vals);
                const minV = Math.min.apply(null, vals);
                const evenSplit = (maxV - minV) <= 0.4 && total >= 6.0;
                if (evenSplit) {
                    ds.evenSplitRun = true;
                    compDelta -= 1.6; jobsDelta -= 8;
                    coachKey = `coach_r3_evensplit`;
                }

                // Retraining & wage-insurance: cushions displaced workers above threshold.
                if (r.retrain >= this.ALLOC_THRESHOLD) { jobsDelta += 30; compDelta += 1.0; }
                else if (r.retrain < 1.0) { jobsDelta -= 10; compDelta -= 0.6; if (coachKey === `coach_default`) coachKey = `coach_r3_noretrain`; }

                // Fiscal-replacement: closes the tariff hole the Finance Minister sees.
                if (r.fiscalRep >= 1.8) { fiscalDelta -= Math.min(this.TARIFF_HOLE, r.fiscalRep * 0.85); }
                else { ds.fiscalHoleRun = true; if (coachKey === `coach_default`) coachKey = `coach_r3_nofiscal`; }

                // Talent-retention: slows the brain drain if it was unleashed.
                if (r.talent >= this.ALLOC_THRESHOLD) {
                    compDelta += 1.4;
                    if (ds.brainDrainRun) { ds.drain = Math.max(4.0, ds.drain - 6.0); ds.brainDrainRun = false; compDelta += 0.6; coachKey = `coach_r3_talentsave`; }
                } else if (r.talent < 1.0 && ds.brainDrainRun) {
                    compDelta -= 1.2; coachKey = `coach_r3_notalent`;
                }

                // SME productivity grants in transformational sectors — slow-burn competitiveness.
                if (r.sme >= 1.5) { compDelta += 0.8; tradeDelta += 0.5; }

                // Trade-facilitation infrastructure — single-window customs, ports.
                if (r.facil >= 1.5) { tradeDelta += 0.7; compDelta += 0.4; }

                // Contingency reserve held (under-spend) gives Round-4 shock headroom.
                const reserve = this.FUND - total;
                if (reserve >= 0.8 && reserve <= 3.0) { compDelta += 0.4; }

                if (!ds.evenSplitRun && r.retrain >= this.ALLOC_THRESHOLD && r.fiscalRep >= 1.8 && (r.talent >= this.ALLOC_THRESHOLD || !ds.brainDrainRun)) {
                    coachKey = `coach_r3_prioritized`;
                }

                summaryKey = ds.evenSplitRun ? `sum_r3_even`
                    : (r.retrain >= this.ALLOC_THRESHOLD && r.fiscalRep >= 1.8 ? `sum_r3_good`
                    : (ds.fiscalHoleRun ? `sum_r3_fiscal` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Recover & Defend: shock response + summit pitch ----
                // The index has dipped to 60.4 — one quarter from the floor.
                ds.comp = Math.min(ds.comp, 60.4);

                switch (d.shock) {
                    case `safeguard`:
                        // Legal, targeted safeguard + accelerated retraining: keeps index up without forfeiting.
                        compDelta += 2.6; jobsDelta += 18; coachKey = `coach_r4_safeguard`; break;
                    case `forfeit`:
                        // Suspending the schedule forfeits the co-financing and the seat.
                        ds.coFinForfeited = true; ds.seatLost = true;
                        compDelta += 1.0; tradeDelta -= 1.6; fiscalDelta += 0.6; coachKey = `coach_r4_forfeit`; break;
                    case `nothing`:
                        // Doing nothing lets the shock push the index through the floor.
                        compDelta -= 2.2; jobsDelta -= 22; coachKey = `coach_r4_nothing`; break;
                }

                switch (d.rebalance) {
                    case `adjust`:
                        // Marginal peso to retraining/wage-insurance — protects floor and people.
                        compDelta += 1.4; jobsDelta += 16; break;
                    case `trade`:
                        tradeDelta += 0.8; compDelta -= 0.6; coachKey = (coachKey === `coach_default`) ? `coach_r4_rebtrade` : coachKey; break;
                    case `none`:
                        if (d.shock === `nothing`) { compDelta -= 0.6; }
                        coachKey = (coachKey === `coach_default`) ? `coach_r4_rebnone` : coachKey; break;
                }

                switch (d.pitch) {
                    case `balanced`:
                        compDelta += 0.8; if (d.shock === `safeguard`) coachKey = `coach_r4_balanced`; break;
                    case `gains`:
                        compDelta -= 0.6; coachKey = `coach_r4_pitchgains`; break;
                    case `protect`:
                        tradeDelta -= 0.4; coachKey = `coach_r4_pitchprotect`; break;
                }

                if (d.conviction >= 60) { compDelta += 0.4; }
                else if (d.conviction <= 25) { compDelta -= 0.3; }

                summaryKey = (d.shock === `safeguard` && d.rebalance === `adjust` && d.pitch === `balanced`)
                    ? `sum_r4_good` : (d.shock === `nothing` ? `sum_r4_floor` : `sum_r4_weak`);
            }

            // ---- Apply deltas (clamped) ----
            ds.trade = Math.max(0, Math.round((ds.trade + tradeDelta) * 10) / 10);
            ds.jobs = Math.round(ds.jobs + jobsDelta);
            ds.comp = Math.round((ds.comp + compDelta) * 10) / 10;
            ds.fiscal = Math.max(0, Math.round((ds.fiscal + fiscalDelta) * 10) / 10);

            // ---- Sticky floor breach: the headline failure. Once the index falls below 60,
            // the schedule is politically dead — the flag stays set and CAPS the KPIs even if a
            // later round nudges the index back up. ----
            if (ds.comp < this.COMP_FLOOR) {
                ds.floorBreached = true;
            }
            if (ds.floorBreached) {
                // A dead schedule cannot bank the full trade gains, and the index is capped low.
                ds.trade = Math.min(ds.trade, this.MAX_GAINS * 0.45);
                ds.comp = Math.min(ds.comp, this.COMP_FLOOR - 0.1);
            }

            // ---- Speed over sequence (headline error): opening ALL sectors at once is a
            // run-defining mistake even if a safeguard buffer keeps the index off the floor.
            // The choice cannot be laundered by good later rounds — cap the competitiveness so it
            // sits right at the floor, never comfortably above it. ----
            if (ds.speedOverSequence) {
                ds.comp = Math.min(ds.comp, 60.5);
            }

            // ---- Fiscal hole: if tariff revenue was never replaced, a structural gap persists. ----
            if (ds.fiscalHoleRun) {
                ds.fiscal = Math.max(ds.fiscal, this.TARIFF_HOLE * 0.7);
            }

            // ---- Co-financing forfeited: a fixed MRD 3.4bn fiscal hit + capped competitiveness. ----
            if (ds.coFinForfeited) {
                ds.fiscal = Math.round((ds.fiscal + 0) * 10) / 10; // (co-financing tracked in fiscal narrative)
                ds.comp = Math.min(ds.comp, 61.5);
            }

            // Clamp competitiveness to a sane band.
            ds.comp = Math.max(40, Math.min(80, Math.round(ds.comp * 10) / 10));

            ds.tradeHistory.push(ds.trade);
            ds.jobsHistory.push(ds.jobs);
            ds.compHistory.push(ds.comp);
            ds.fiscalHistory.push(ds.fiscal);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // ── Persist the composite where the grading/reporting layer reads it ──
            // express_resolveDomainScore() → domainState.performance.overallScore (then top-level score);
            // express_extractHistory() reads the SAME path from each period's history snapshot;
            // express_compute_grade() (gametype 20) posts it back via AGS. Without this the
            // gradebook shows "—", the sparkline is empty and every LTI grade is 0.
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.performance.grade = this._gradeLetter(composite);
            ds.score = composite;

            return {
                period: state.currentPeriod,
                trade: ds.trade,
                tradeDelta: Math.round(tradeDelta * 10) / 10,
                jobs: ds.jobs,
                jobsDelta: Math.round(jobsDelta),
                comp: ds.comp,
                compDelta: Math.round(compDelta * 10) / 10,
                fiscal: ds.fiscal,
                fundUsed: ds.fundUsed,
                drain: ds.drain,
                floorBreached: ds.floorBreached,
                coFinForfeited: ds.coFinForfeited,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

        _floorLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const ds = window.mySimulation ? window.mySimulation.state.domainState : null;
            if (ds && ds.floorBreached) return t(`floor_breached`);
            if (v < 61) return t(`floor_warn`);
            return t(`floor_above`);
        }

        // ── Composite score (0-100). VERBATIM v1.0.0 formula + sticky caps from
        //    getPerformanceSummary, factored into a helper so calculateResults persists it
        //    every period and getPerformanceSummary reuses it (persisted == completion). ──
        _composite(ds) {
            const trade = Math.round((ds.trade || 0) * 10) / 10;
            const jobs = Math.round(ds.jobs || 0);
            const comp = Math.round((ds.comp || 0) * 10) / 10;
            const fiscal = Math.round((ds.fiscal || 0) * 10) / 10;
            const tradeScore = Math.min(100, (trade / this.MAX_GAINS) * 100);
            const jobsScore = Math.max(0, Math.min(100, (jobs + 90) / 1.5));
            const compScore = Math.max(0, Math.min(100, (comp - 58) / 0.12));
            const fiscalScore = Math.max(0, 100 - (fiscal / this.TARIFF_HOLE) * 100);
            let composite = Math.round(
                tradeScore * 0.28 + jobsScore * 0.24 + compScore * 0.30 + fiscalScore * 0.18
            );
            if (ds.floorBreached) composite = Math.min(composite, 42);
            if (ds.speedOverSequence) composite = Math.min(composite, 56);
            if (ds.coFinForfeited) composite = Math.min(composite, 58);
            if (ds.brainDrainRun) composite = Math.min(composite, 60);
            if (ds.evenSplitRun) composite = Math.min(composite, 62);
            if (ds.fiscalHoleRun) composite = Math.min(composite, 64);
            return composite;
        }

        // Letter band for the instructor gradebook (express_extractMetrics reads
        // domainState.performance.grade; AGS post-back carries it as grade_letter).
        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 70) return `B`;
            if (c >= 55) return `C`;
            if (c >= 40) return `D`;
            return `F`;
        }

        // Localized label for a verdict tier — English tier id stays the internal key.
        _gradeLabel(perfKey) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Integration Sequenced': 'verdict_sequenced',
                'Schedule at Risk': 'verdict_atrisk',
                'Floor Breached': 'verdict_floor',
                'Speed Over Sequence': 'verdict_speed',
                'Seat Forfeited': 'verdict_seat',
                'Workable Schedule': 'verdict_workable',
                'Mixed Outcome': 'verdict_mixed'
            };
            const key = map[perfKey];
            return key ? t(key) : perfKey;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`tradeDisplay`, `domainState.trade`, (v) => `MRD ${self._num1(Number(v))} bn`);

            uiManager.bind(`jobsDisplay`, `domainState.jobs`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.maritima-card-jobs`);
                if (card) {
                    card.classList.toggle(`maritima-jobs-good`, n >= 0);
                    card.classList.toggle(`maritima-jobs-bad`, n < 0);
                }
                const sign = n > 0 ? `+` : ``;
                return `${sign}${self._numK(n)}`;
            });

            uiManager.bind(`compDisplay`, `domainState.comp`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.maritima-card-comp`);
                if (card) {
                    const breached = window.mySimulation.state.domainState.floorBreached || n < self.COMP_FLOOR;
                    card.classList.toggle(`maritima-comp-danger`, breached);
                    card.classList.toggle(`maritima-comp-warn`, !breached && n < 61);
                }
                return self._num1(n);
            });

            uiManager.bind(`fiscalDisplay`, `domainState.fiscal`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.maritima-card-fiscal`);
                if (card) {
                    card.classList.toggle(`maritima-fiscal-bad`, n >= 0.5);
                    card.classList.toggle(`maritima-fiscal-good`, n < 0.5);
                }
                return `MRD ${self._num1(n)} bn`;
            });

            uiManager.bind(`floorDisplay`, `domainState.comp`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.maritima-floor-bar`);
                if (bar) {
                    const breached = window.mySimulation.state.domainState.floorBreached || n < self.COMP_FLOOR;
                    bar.classList.toggle(`maritima-floor-danger`, breached);
                    bar.classList.toggle(`maritima-floor-warn`, !breached && n < 61);
                }
                return self._floorLabel(n);
            });

            uiManager.bind(`fundDisplay`, `domainState.fundUsed`, (v) => `MRD ${self._num1(Number(v))} bn / ${self._num1(self.FUND)} bn`);

            uiManager.bind(`drainDisplay`, `domainState.drain`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.maritima-drain-bar`);
                if (bar) bar.classList.toggle(`maritima-drain-bad`, n >= 10);
                if (n <= 0) return `—`;
                return `${self._num1(n)}k ` + window.mySimulation.t(`drain_unit`);
            });

            // Slider readouts.
            this._wireSlider(`rigourInput`, `rigourReadout`);
            this._wireSlider(`safeguardInput`, `safeguardReadout`);

            // Live fund-allocation readout.
            const allocFields = [`retrainInput`, `fiscalRepInput`, `talentInput`, `smeInput`, `facilInput`];
            const allocEl = document.getElementById(`allocReadout`);
            const remainEl = document.getElementById(`allocRemain`);
            const recompute = function() {
                let total = 0;
                allocFields.forEach((id) => {
                    const el = document.getElementById(id);
                    const v = el ? parseFloat(el.value) : 0;
                    if (Number.isFinite(v)) total += v;
                });
                total = Math.round(total * 10) / 10;
                if (allocEl) allocEl.textContent = `MRD ${self._num1(total)} bn / ${self._num1(self.FUND)} bn`;
                if (remainEl) {
                    const remain = Math.round((self.FUND - total) * 10) / 10;
                    remainEl.classList.toggle(`maritima-alloc-over`, remain < 0);
                    remainEl.classList.toggle(`maritima-alloc-ok`, remain >= 0);
                    const key = remain < 0 ? `alloc_over_by` : `alloc_reserve`;
                    remainEl.textContent = window.mySimulation.t(key) + ` MRD ` + self._num1(Math.abs(remain)) + ` bn`;
                }
            };
            allocFields.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _wireSlider(inputId, readoutId) {
            const inp = document.getElementById(inputId);
            const out = document.getElementById(readoutId);
            if (inp && out) {
                out.textContent = inp.value;
                inp.addEventListener(`input`, function() { out.textContent = inp.value; });
            }
        }

        _num1(v) {
            // Locale-aware one-decimal: en "2.4", es "2,4".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(Number(v) * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        _numK(n) {
            // Jobs are in thousands; show as e.g. "60k".
            return `${Math.round(n)}k`;
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation)
                : (k) => ({ chart_ds_comp: `Competitiveness index`, chart_ds_trade: `Trade gains (MRD bn ×10)`, chart_ds_jobs: `Net jobs (thousands, +60 offset)`, chart_axis_left: `index · gains×10 · jobs+60`, chart_axis_round: `Round` }[k] || k);
            return {
                maritimaChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t(`chart_ds_comp`),
                                data: [],
                                borderColor: `#b8902f`,
                                backgroundColor: `rgba(184,144,47,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#b8902f`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_trade`),
                                data: [],
                                borderColor: `#0c8f7a`,
                                backgroundColor: `rgba(12,143,122,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#0c8f7a`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_jobs`),
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
