        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.compHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Trade is small (MRD bn) — scale ×10. Jobs swing negative — offset +60 to share the 0–100 axis.
            const tradeScaled = ds.tradeHistory.map((v) => Math.round(v * 10));
            const jobsScaled = ds.jobsHistory.map((v) => Math.max(0, Math.min(100, Math.round(v + 60))));
            return {
                maritimaChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.compHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: tradeScaled },
                        { data: jobsScaled }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trade = Math.round(ds.trade * 10) / 10;
            const jobs = Math.round(ds.jobs);
            const comp = Math.round(ds.comp * 10) / 10;
            const fiscal = Math.round(ds.fiscal * 10) / 10;

            // KPI pass tests.
            const floorHeld = !ds.floorBreached && comp >= this.COMP_FLOOR;
            const goodTrade = trade >= 3.5;
            const jobsCushioned = jobs >= -25;
            const fiscalCovered = !ds.fiscalHoleRun && fiscal <= 0.8;
            const seatKept = !ds.coFinForfeited;

            // Composite (0–100) — factored into _composite(ds) so calculateResults persists
            // the identical value every period (persisted == completion by construction).
            const composite = this._composite(ds);

            // Pattern label. (speedOverSequence is the headline error — surface it even when a
            // buffer kept the index off the floor.)
            let pattern = `mixed`;
            if (ds.floorBreached || ds.speedOverSequence) pattern = `speed`;
            else if (ds.coFinForfeited && trade < 2.0) pattern = `protectionism`;
            else if (ds.brainDrainRun) pattern = `braindrain`;
            else if (ds.evenSplitRun) pattern = `evensplit`;
            else if (ds.fiscalHoleRun) pattern = `fiscalhole`;
            else if (floorHeld && goodTrade && jobsCushioned && fiscalCovered && seatKept) pattern = `sequenced`;

            // Verdict — the TOP verdict is unreachable unless every sticky flag is clear,
            // including the headline speed-over-sequence error.
            let performance = `Schedule at Risk`;
            if (floorHeld && !ds.speedOverSequence && goodTrade && jobsCushioned && fiscalCovered && seatKept && composite >= 78) {
                performance = `Integration Sequenced`;
            } else if (ds.floorBreached) {
                performance = `Floor Breached`;
            } else if (ds.speedOverSequence) {
                performance = `Speed Over Sequence`;
            } else if (ds.coFinForfeited && trade < 2.0) {
                performance = `Seat Forfeited`;
            } else if (floorHeld && seatKept && composite >= 60) {
                performance = `Workable Schedule`;
            } else if (composite >= 50) {
                performance = `Mixed Outcome`;
            }

            const insights = [];
            if (pattern === `sequenced`) insights.push(window.mySimulation.t(`insight_sequenced`));
            else if (ds.floorBreached) insights.push(window.mySimulation.t(`insight_speed`));
            else if (ds.speedOverSequence) insights.push(window.mySimulation.t(`insight_speed_buffered`));
            else if (pattern === `protectionism`) insights.push(window.mySimulation.t(`insight_protectionism`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.brainDrainRun) insights.push(window.mySimulation.t(`insight_braindrain`));
            if (ds.evenSplitRun) insights.push(window.mySimulation.t(`insight_evensplit`));
            if (ds.fiscalHoleRun) insights.push(window.mySimulation.t(`insight_fiscalhole`));
            if (ds.coFinForfeited) insights.push(window.mySimulation.t(`insight_seat`));
            if (goodTrade && !floorHeld) insights.push(window.mySimulation.t(`insight_gains_hollow`));

            return {
                trade: trade,
                jobs: jobs,
                comp: comp,
                fiscal: fiscal,
                floorHeld: floorHeld,
                goodTrade: goodTrade,
                jobsCushioned: jobsCushioned,
                fiscalCovered: fiscalCovered,
                seatKept: seatKept,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        // ── Localized completion debrief. The base class discards the composite,
        //    verdict, target status and insights the sim already computes and prints a
        //    generic "You completed N periods." This override surfaces them. ──
        formatCompletionMessage(summary) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = (summary && typeof summary === `object`) ? summary : {};
            const ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState)
                ? window.mySimulation.state.domainState : {};
            const composite = (s.composite != null) ? s.composite : this._composite(ds);
            const verdict = this._gradeLabel(s.performance || `Schedule at Risk`);
            const grade = this._gradeLetter(composite);
            const trade = (s.trade != null) ? s.trade : Math.round((ds.trade || 0) * 10) / 10;
            const jobs = (s.jobs != null) ? s.jobs : Math.round(ds.jobs || 0);
            const comp = (s.comp != null) ? s.comp : Math.round((ds.comp || 0) * 10) / 10;
            const fiscal = (s.fiscal != null) ? s.fiscal : Math.round((ds.fiscal || 0) * 10) / 10;
            const floorHeld = (s.floorHeld != null) ? s.floorHeld : (!ds.floorBreached && comp >= this.COMP_FLOOR);
            const seatKept = (s.seatKept != null) ? s.seatKept : !ds.coFinForfeited;
            const insights = Array.isArray(s.insights) ? s.insights : [];

            const jobsStr = `${jobs > 0 ? `+` : ``}${this._numK ? this._numK(jobs) : jobs}`;
            const met = (ok) => ok
                ? `<span class="ir-cm-chip ir-cm-chip-ok">✓ ${t(`cm_met`)}</span>`
                : `<span class="ir-cm-chip ir-cm-chip-no">✗ ${t(`cm_missed`)}</span>`;

            const kpis = [
                { label: t(`cm_kpi_trade`), val: `MRD ${this._num1(trade)} bn` },
                { label: t(`cm_kpi_jobs`), val: jobsStr },
                { label: t(`cm_kpi_comp`), val: this._num1(comp) },
                { label: t(`cm_kpi_fiscal`), val: `MRD ${this._num1(fiscal)} bn` }
            ].map((k) => `<div class="ir-cm-kpi"><div class="ir-cm-kpi-val">${k.val}</div><div class="ir-cm-kpi-lbl">${k.label}</div></div>`).join(``);

            const insightsHtml = insights.length
                ? `<div class="ir-cm-insights-wrap"><div class="ir-cm-insights-label">${t(`cm_insights_label`)}</div><ul class="ir-cm-insights">${insights.map((i) => `<li>${i}</li>`).join(``)}</ul></div>`
                : ``;

            const tierClass = `ir-cm-tier-` + (composite >= 78 ? `top` : (composite >= 50 ? `mid` : `low`));

            return `
                <div class="ir-cm ${tierClass}">
                    <div class="ir-cm-head">
                        <div class="ir-cm-score"><span class="ir-cm-score-num">${composite}</span><span class="ir-cm-score-den">/100</span></div>
                        <div class="ir-cm-headmeta">
                            <div class="ir-cm-title">${t(`cm_title`)}</div>
                            <div class="ir-cm-verdict">${verdict} <span class="ir-cm-grade">${grade}</span></div>
                        </div>
                    </div>
                    <div class="ir-cm-kpis">${kpis}</div>
                    <div class="ir-cm-targets">
                        <span class="ir-cm-tgt-label">${t(`cm_targets_label`)}</span>
                        <span class="ir-cm-tgt">${t(`cm_target_floor`)} ${met(floorHeld)}</span>
                        <span class="ir-cm-tgt">${t(`cm_target_seat`)} ${met(seatKept)}</span>
                    </div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.floorBreached) return window.mySimulation.t(`hint_floor`);
            if (ds.comp < 61) return window.mySimulation.t(`hint_nearfloor`);
            if (ds.brainDrainRun && state.currentPeriod >= 2) return window.mySimulation.t(`hint_braindrain`);
            if (ds.coFinForfeited) return window.mySimulation.t(`hint_seat`);
            if (ds.fiscalHoleRun && state.currentPeriod >= 3) return window.mySimulation.t(`hint_fiscal`);
            if (ds.comp >= 62 && ds.trade >= 3.0 && ds.fiscal <= 0.8) return window.mySimulation.t(`hint_strong`);
            return null;
        }

